<template><span class="sf-icon" aria-hidden="true"><span v-if="assetName" class="sf-icon__asset" :data-icon="name" :style="assetStyle"/><app-icon v-else-if="legacyNames.includes(name)" :name="name" :size="size"/><svg v-else :width="size" :height="size" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path v-if="name==='close'" d="M6 6l12 12M18 6 6 18"/><template v-else-if="name==='search'"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/></template><template v-else-if="name==='eye'"><path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></template><template v-else-if="name==='eye-off'"><path d="m3 3 18 18M9.8 5.2A12 12 0 0 1 12 5c7 0 10 7 10 7a17 17 0 0 1-3.2 4.2M6 6a19 19 0 0 0-4 6s3 7 10 7a12 12 0 0 0 5-1.1"/></template><path v-else-if="name==='plus'" d="M12 5v14M5 12h14"/><path v-else-if="name==='minus'" d="M5 12h14"/><template v-else-if="name==='more'"><circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/></template><path v-else-if="name==='refresh'" d="M20 8V3l-3 3a8 8 0 1 0 3 8M20 8h-5"/><template v-else><circle cx="12" cy="12" r="9"/><path d="M12 7v6M12 17h.01"/></template></svg></span></template>
<script>
import AppIcon from '@/views/app/AppIcon'
const menuAssets={'heart-pulse':'heart-pulse','receipt-text':'receipt-text','users-round':'users-round',settings:'settings','circle-question-mark':'circle-question-mark','user-round-plus':'user-round-plus','shopping-bag':'shopping-bag',membership:'crown'}
export default {name:'SfIcon',components:{AppIcon},props:{name:{type:String,required:true},size:{type:[Number,String],default:22}},data(){return {legacyNames:['arrow','back','wallet','crown','coach','user','play','lock','spark','check','calendar']}},computed:{assetName(){return Object.prototype.hasOwnProperty.call(menuAssets,this.name)?menuAssets[this.name]:null},assetStyle(){const url='url("/assets/icons/profile-menu/'+this.assetName+'.svg")',size=String(this.size).match(/^\d+(\.\d+)?$/)?this.size+'px':this.size;return {width:size,height:size,maskImage:url,WebkitMaskImage:url}}}}
</script>
